from typing import List, Dict, Any, Optional, Callable
from leann.api import SearchResult
from leann.metadata_filter import MetadataFilterEngine
from collections import defaultdict


def apply_dynamic_filters(
    search_results: List[SearchResult],
    filter_specs: Dict[str, Dict[str, Any]],
    filter_logic: str = "AND"
) -> List[SearchResult]:
    """Apply dynamic metadata filters to search results with configurable logic.

    Args:
        search_results: List of SearchResult objects to filter
        filter_specs: Dictionary of filter specifications.
            Format: {"field_name": {"operator": value}}
            Example: {"category": {"==": "tech"}, "rating": {">=": 4.0}}
        filter_logic: "AND" (all filters must match) or "OR" (any filter matches)

    Returns:
        Filtered list of SearchResult objects
    """
    if not search_results or not filter_specs:
        return search_results

    # Initialize the metadata filter engine
    filter_engine = MetadataFilterEngine()

    # Convert SearchResult objects to dictionaries for filtering
    results_as_dicts = []
    for result in search_results:
        result_dict = {
            "metadata": getattr(result, 'metadata', {}),
            "score": getattr(result, 'score', 0.0),
            "doc_id": getattr(result, 'doc_id', None),
            "content": getattr(result, 'content', ""),
            # Include other relevant attributes from SearchResult
            "original_object": result  # Keep reference to original object
        }
        results_as_dicts.append(result_dict)

    # Apply filters based on the specified logic
    if filter_logic.upper() == "AND":
        # AND logic: results must match all filters
        filtered_dicts = results_as_dicts
        for field_name, operator_dict in filter_specs.items():
            if not operator_dict:
                continue
            for operator, value in operator_dict.items():
                if operator in filter_engine.operators:
                    # Create a single filter for this field/operator/value
                    field_filter = {field_name: {operator: value}}
                    filtered_dicts = filter_engine.apply_filters(filtered_dicts, field_filter)

    elif filter_logic.upper() == "OR":
        # OR logic: results must match at least one filter
        filtered_dicts = []
        matched_indices = set()

        for field_name, operator_dict in filter_specs.items():
            if not operator_dict:
                continue
            for operator, value in operator_dict.items():
                if operator in filter_engine.operators:
                    # Create a single filter for this field/operator/value
                    field_filter = {field_name: {operator: value}}
                    # Apply this specific filter
                    partial_results = filter_engine.apply_filters(results_as_dicts, field_filter)

                    # Track indices of matching results
                    for i, original_dict in enumerate(results_as_dicts):
                        if original_dict in partial_results and i not in matched_indices:
                            matched_indices.add(i)
                            filtered_dicts.append(original_dict)

    else:
        raise ValueError(f"Unsupported filter logic: {filter_logic}. Use 'AND' or 'OR'.")

    # Convert back to SearchResult objects, maintaining original structure
    filtered_results = []
    for result_dict in filtered_dicts:
        # Return the original SearchResult object that was preserved
        filtered_results.append(result_dict["original_object"])

    return filtered_results
