from typing import List, Dict, Any
from leann.api import PassageManager, LeannSearcher
from pathlib import Path
import json
from collections import Counter, defaultdict

def get_index_statistics(
    index_path: str
) -> Dict[str, Any]:
    """Get comprehensive statistics about a LEANN index.

Args:
    index_path: Path to the LEANN index file

Returns:
    Dictionary containing:
    {
        "total_passages": total number of passages,
        "metadata_fields": list of unique metadata field names,
        "field_value_counts": dictionary of field value counts
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""

    # Check if the index file exists
    index_path_obj = Path(index_path)
    if not index_path_obj.exists():
        raise FileNotFoundError(f"Index file not found: {index_path}")

    # Use PassageManager to load the index and get statistics
    try:
        # Load the passage manager
        passage_manager = PassageManager(index_path=index_path)

        # Get all passages to analyze metadata
        all_passages = passage_manager.get_all_passages()
        total_passages = len(all_passages)

        # Collect all unique metadata field names
        metadata_fields = set()
        field_value_counts = defaultdict(Counter)

        for passage in all_passages:
            if hasattr(passage, 'metadata') and passage.metadata:
                # Add all field names to the set
                metadata_fields.update(passage.metadata.keys())

                # Count values for each field
                for field, value in passage.metadata.items():
                    # Convert value to string for counting if it's not a basic type
                    if isinstance(value, (list, dict)):
                        value_str = json.dumps(value, sort_keys=True)
                    else:
                        value_str = str(value)
                    field_value_counts[field][value_str] += 1

        # Convert field_value_counts to regular dict with regular dicts
        field_value_counts_regular = {}
        for field, counter in field_value_counts.items():
            field_value_counts_regular[field] = dict(counter)

        return {
            "total_passages": total_passages,
            "metadata_fields": sorted(list(metadata_fields)),
            "field_value_counts": field_value_counts_regular
        }

    except Exception as e:
        # If there's an error loading the index, treat it as file not found
        if "not found" in str(e).lower() or "does not exist" in str(e).lower():
            raise FileNotFoundError(f"Index metadata file not found: {index_path}") from e
        raise

def analyze_index_coverage(index_path: str, required_fields: List[str]) -> Dict[str, Any]:
    """Analyze how well an index covers required metadata fields.

Args:
    index_path: Path to the LEANN index file
    required_fields: List of metadata field names that should be present

Returns:
    Dictionary containing:
    {
        "coverage_percentage": percentage of passages that have all required fields,
        "field_coverage": dictionary mapping field name to coverage percentage,
        "missing_fields": list of required fields not found in any passage
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""

    # Check if the index file exists
    index_path_obj = Path(index_path)
    if not index_path_obj.exists():
        raise FileNotFoundError(f"Index file not found: {index_path}")

    # Use PassageManager to load the index and analyze coverage
    try:
        # Load the passage manager
        passage_manager = PassageManager(index_path=index_path)

        # Get all passages to analyze coverage
        all_passages = passage_manager.get_all_passages()
        total_passages = len(all_passages)

        if total_passages == 0:
            return {
                "coverage_percentage": 0.0,
                "field_coverage": {field: 0.0 for field in required_fields},
                "missing_fields": required_fields.copy()
            }

        # Initialize counters
        passages_with_all_fields = 0
        field_presence_count = {field: 0 for field in required_fields}

        for passage in all_passages:
            if hasattr(passage, 'metadata') and passage.metadata:
                passage_metadata_fields = set(passage.metadata.keys())

                # Check if this passage has all required fields
                has_all_fields = all(field in passage_metadata_fields for field in required_fields)
                if has_all_fields:
                    passages_with_all_fields += 1

                # Count presence of each individual field
                for field in required_fields:
                    if field in passage_metadata_fields:
                        field_presence_count[field] += 1

        # Calculate percentages
        coverage_percentage = (passages_with_all_fields / total_passages) * 100

        field_coverage = {}
        for field in required_fields:
            field_coverage[field] = (field_presence_count[field] / total_passages) * 100

        # Find fields that are missing from all passages
        missing_fields = [field for field in required_fields if field_presence_count[field] == 0]

        return {
            "coverage_percentage": coverage_percentage,
            "field_coverage": field_coverage,
            "missing_fields": missing_fields
        }

    except Exception as e:
        # If there's an error loading the index, treat it as file not found
        if "not found" in str(e).lower() or "does not exist" in str(e).lower():
            raise FileNotFoundError(f"Index metadata file not found: {index_path}") from e
        raise
